/** 명세서 기준 되묻기 분석 실행 API입니다. */
package com.dandimate.durooduroo.askback.controller;
import com.dandimate.durooduroo.askback.domain.Askback; import com.dandimate.durooduroo.askback.repository.AskbackRepository; import com.dandimate.durooduroo.askback.service.AskbackRuleService; import com.dandimate.durooduroo.ai.domain.AiJob; import com.dandimate.durooduroo.ai.repository.AiJobRepository; import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.auth.MemberTokenResolver; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.domain.MemberRole; import com.dandimate.durooduroo.member.repository.MemberRepository; import com.dandimate.durooduroo.room.repository.RoomRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController public class AskbackRunController { private final RoomRepository rooms;private final MemberRepository members;private final AskbackRepository askbacks;private final AiJobRepository jobs;private final AskbackRuleService rules; public AskbackRunController(RoomRepository r,MemberRepository m,AskbackRepository a,AiJobRepository j,AskbackRuleService rules){rooms=r;members=m;askbacks=a;jobs=j;this.rules=rules;} @PostMapping("/api/v1/rooms/{roomId}/askbacks/run") public ResponseEntity<ApiResponse<?>> run(@PathVariable String roomId,@RequestHeader(required=false) String authorization,@RequestParam(required=false) String memberToken){rooms.findById(roomId).orElseThrow(()->new BusinessException("ROOM_NOT_FOUND","존재하지 않는 방입니다."));String token=MemberTokenResolver.resolve(authorization,memberToken);var host=members.findByRoomIdAndMemberToken(roomId,token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","방 참여자만 실행할 수 있습니다."));if(host.getRole()!=MemberRole.HOST)throw new BusinessException("HOST_ONLY","방장만 실행할 수 있습니다.");var target=members.findAllByRoomId(roomId).stream().filter(m->m.getRole()!=MemberRole.HOST).findFirst();var rule=rules.decide(roomId);if(target.isPresent())askbacks.save(Askback.create(roomId,target.get().getId(),rule.question()));AiJob job=jobs.save(AiJob.queued(roomId));job.succeed();jobs.save(job);return ResponseEntity.status(HttpStatus.ACCEPTED).body(ApiResponse.success(Map.of("job",Map.of("id",job.getId(),"type","ASKBACK_ANALYZE","status",job.getStatus()),"gapType",rule.gapType(),"question",rule.question())));}}
